    int rank = 0;
    for (int i = 0; i < n; i++) {
        cin >> x;
        x |= 1ULL << 60;
        for (int k = 60; k >= 0; k--)
            if (x >> k & 1) {
                if (b[k])
                    x ^= b[k];
                else {
                    b[k] = x;
                    rank++;
                    break;
                }
            }
    }
    x = p ? (b[60] ^ (1ULL << 60)) : 0;
    for (int k = 59; k >= 0; k--)
        x = max(x, x ^ b[k]);
    cout << x << ' ' << (1ULL << (n - rank)) << '\n';
}

