int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, s, t;
    cin >> n >> m >> s >> t;
    --s;
    --t;
    vector<array<vector<int>, 2>> g(n);
    while (m--) {
        int u, v, c;
        cin >> u >> v >> c;
        --u;
        --v;
        g[u][c].push_back(v);
        g[v][c].push_back(u);
    }
    vector<int> d(n * n, -1);
    queue<pair<int, int>> q;
    d[t * n + s] = 0;
    q.push({t, s});
    auto nexts = [&](int u, int v, auto f) {
        for (int c = 0; c < 2; c++)
            for (int x : g[u][c])
                for (int y : g[v][c])
                    if (x != y && !(x == v && y == u))
                        f(x, y);
    };
    while (!q.empty()) {
        auto [u, v] = q.front();
        q.pop();
        nexts(u, v, [&](int x, int y) {
            if (d[x * n + y] < 0) {
                d[x * n + y] = d[u * n + v] + 1;
                q.push({x, y});
            }
        });
    }
    int D = d[s * n + t];
    if (D < 0) {
        cout << "-1 0 0\n";
        return 0;
    }
    pair<int, int> a = {n, n};
    nexts(s, t, [&](int x, int y) {
        if (d[x * n + y] == D - 1)
            a = min(a, make_pair(x, y));
    });
    cout << D << ' ' << a.first + 1 << ' ' << a.second + 1 << '\n';
}

