it = iter(map(int, sys.stdin.buffer.read().split()))
n, m, s, t = [next(it) for _ in range(4)]
s -= 1
t -= 1
g = [[[], []] for _ in range(n)]
for _ in range(m):
    u, v, c = next(it) - 1, next(it) - 1, next(it)
    g[u][c].append(v)
    g[v][c].append(u)


def neighbors(u, v):
    for c in range(2):
        for x in g[u][c]:
            for y in g[v][c]:
                if x != y and not (x == v and y == u):
                    yield x, y


d = [-1] * (n * n)
d[t * n + s] = 0
q = deque([(t, s)])
while q:
    u, v = q.popleft()
    for x, y in neighbors(u, v):
        if d[x * n + y] < 0:
            d[x * n + y] = d[u * n + v] + 1
            q.append((x, y))
D = d[s * n + t]
if D < 0:
    print(-1, 0, 0)
else:
    x, y = min((x, y) for x, y in neighbors(s, t) if d[x * n + y] == D - 1)
    print(D, x + 1, y + 1)

