using namespace std;
using ll = long long;
int main() {
    ll N;
    cin >> N;
    ll z = N;
    vector<pair<ll, int>> f;
    for (ll p = 2; p * p <= z; p++)
        if (z % p == 0) {
            int e = 0;
            while (z % p == 0)
                z /= p, e++;
            f.push_back({p, e});
        }
    if (z > 1)
        f.push_back({z, 1});
    vector<ll> d{1};
    for (auto [p, e] : f) {
        int k = d.size();
        ll v = 1;
        for (int j = 1; j <= e; j++) {
            v *= p;
            for (int i = 0; i < k; i++)
                d.push_back(d[i] * v);
        }
    }
    sort(d.begin(), d.end());
    ll cnt = 0;
    array<ll, 4> best = {LLONG_MAX, 0, 0, 0};
    for (ll a : d) {
        if (a > N / a / a)
            break;
        ll rem = N / a;
        for (ll b : d) {
            if (b < a)
                continue;
            if (b > rem / b)
                break;
            if (rem % b)
                continue;
            ll c = rem / b;
            if (gcd(a, b) > 1 && gcd(a, c) > 1 && gcd(b, c) > 1 &&
                gcd(gcd(a, b), c) == 1) {
                cnt++;
                best = min(best, array<ll, 4>{c - a, a, b, c});
            }
        }
    }
    if (!cnt)
        cout << "0 -1\n-\n";
    else
        cout << cnt << ' ' << best[0] << '\n'
             << best[1] << ' ' << best[2] << ' ' << best[3] << '\n';
}

