#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, s, t;
    cin >> n >> m >> s >> t;
    struct E {
        int v;
        ll w;
        int mask, value;
    };
    vector<vector<E>> g(n);
    for (int i = 0; i < m; i++) {
        int u, v, ma, va;
        ll w;
        cin >> u >> v >> w >> ma >> va;
        g[u - 1].push_back({v - 1, w, ma, va});
    }
    int Z = 1 << n;
    ll INF = LLONG_MAX / 4;
    vector<ll> d(n * Z, INF);
    vector<int> ways(n * Z);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> q;
    d[s] = 0;
    ways[s] = 1;
    q.push({0, s});
    while (!q.empty()) {
        auto [du, id] = q.top();
        q.pop();
        if (d[id] != du)
            continue;
        int u = id / Z, x = id % Z;
        for (auto e : g[u])
            if ((x & e.mask) == e.value) {
                int j = e.v * Z + (x ^ (1 << e.v));
                ll nd = du + e.w;
                if (nd < d[j]) {
                    d[j] = nd;
                    ways[j] = ways[id];
                    q.push({nd, j});
                } else if (nd == d[j])
                    ways[j] = (ways[j] + ways[id]) % 101;
            }
    }
    int goal = (n - 1) * Z + t;
    if (d[goal] == INF)
        cout << "-1 0\n";
    else
        cout << d[goal] << ' ' << ways[goal] << '\n';
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using I = __int128_t;
ll eg(ll a, ll b, ll &x, ll &y) {
    if (!b) {
        x = 1;
        y = 0;
        return a;
    }
    ll u, v;
    ll g = eg(b, a % b, u, v);
    x = v;
    y = u - (a / b) * v;
    return g;
}
void out(I x) {
    if (x >= 10)
        out(x / 10);
    cout << char('0' + x % 10);
}
int main() {
    ll p, a, q, b, K;
    cin >> p >> a >> q >> b >> K;
    if (p == q && a == b) {
        cout << "IMPOSSIBLE\n";
        return 0;
    }
    ll g = gcd(p, q), xx, yy;
    I L = I(p / g) * q, r = -1;
    if ((b - a) % g == 0) {
        eg(p / g, q / g, xx, yy);
        ll mod = q / g;
        I k = (I((b - a) / g) * xx % mod + mod) % mod;
        r = (a + I(p) * k) % L;
    }
    auto cnt = [](I T, I start, I period) -> I {
        return T < start ? 0 : (T - start) / period + 1;
    };
    auto F = [&](I T) {
        return cnt(T, a, p) + cnt(T, b, q) - (r < 0 ? 0 : 2 * cnt(T, r, L));
    };
    I hi = 1, lo = 0;
    while (F(hi) < K)
        hi *= 2;
    while (lo < hi) {
        I mid = (lo + hi) / 2;
        if (F(mid) >= K)
            hi = mid;
        else
            lo = mid + 1;
    }
    out(lo);
    cout << ' ' << (lo % p == a ? 'A' : 'B') << '\n';
}

