    mod = q // g
    k = 0 if mod == 1 else ((b - a) // g * pow(p // g, -1, mod)) % mod
    r = (a + p * k) % L


def count(T, start, period):
    return 0 if T < start else (T - start) // period + 1


def F(T):
    return count(T, a, p) + count(T, b, q) - (0 if r is None else 2 * count(T, r, L))


lo = 0
hi = 1
while F(hi) < K:
    hi *= 2
while lo < hi:
    mid = (lo + hi) // 2
    if F(mid) >= K:
        hi = mid
    else:
        lo = mid + 1
print(lo, "A" if lo % p == a else "B")

