#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    int D, M;
    cin >> D >> M;
    vector<vector<tuple<int, int, ll>>> arr(D + 1);
    for (int i = 0; i < M; i++) {
        int a, e;
        char t;
        ll q;
        cin >> a >> e >> t >> q;
        int k = t == 'A' ? 0 : t == 'B' ? 1 : 2;
        arr[a].push_back({e, k, q});
    }
    using Q =
        priority_queue<pair<int, ll>, vector<pair<int, ll>>, greater<pair<int, ll>>>;
    array<Q, 3> h;
    ll lost = 0, A = 0, B = 0;
    auto take = [&](int k, ll need) {
        while (need && !h[k].empty()) {
            auto [e, q] = h[k].top();
            h[k].pop();
            ll z = min(q, need);
            q -= z;
            need -= z;
            if (q)
                h[k].push({e, q});
        }
        return need;
    };
    for (int day = 1; day <= D; day++) {
        ll a, b;
        cin >> a >> b;
        for (auto &v : h)
            while (!v.empty() && v.top().first < day) {
                lost += v.top().second;
                v.pop();
            }
        for (auto [e, k, q] : arr[day])
            h[k].push({e, q});
        a = take(0, a);
        b = take(1, b);
        if (a >= b) {
            a = take(2, a);
            b = take(2, b);
        } else {
            b = take(2, b);
            a = take(2, a);
        }
        A += a;
        B += b;
    }
    ll rem = 0;
    for (auto &v : h)
        while (!v.empty()) {
            rem += v.top().second;
            v.pop();
        }
    cout << A << ' ' << B << ' ' << lost << ' ' << rem << '\n';
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> a(n);
    for (auto &[x, y] : a)
        cin >> x >> y;
    unordered_map<ll, pair<int, ll>> memo;
    int full = (1 << n) - 1, INF = 100;
    function<pair<int, ll>(int, int, int, int)> go = [&](int mask, int l, int r,
                                                         int sg) -> pair<int, ll> {
        if (mask == full)
            return {0, 1};
        ll key = (((ll(mask) * 10 + l) * 10 + r) * 3 + sg);
        if (memo.count(key))
            return memo[key];
        pair<int, ll> best = {INF, 0};
        for (int i = 0; i < n; i++)
            if (!(mask >> i & 1))
                for (int o = 0; o < 2; o++) {
                    int x = o ? a[i].second : a[i].first,
                        y = o ? a[i].first : a[i].second;
                    if (x != r)
                        continue;
                    int ns = sg;
                    if (__builtin_popcount((unsigned)mask) >= 2) {
                        if (l == r)
                            continue;
                        ns = r > l ? 1 : 2;
                        if (ns == sg)
                            continue;
                    }
                    auto [v, c] = go(mask | 1 << i, x, y, ns);
                    v += o;
                    if (v < best.first)
                        best = {v, c};
                    else if (v == best.first)
                        best.second += c;
                }
        return memo[key] = best;
    };
    pair<int, ll> ans = {INF, 0};
    for (int i = 0; i < n; i++)
        for (int o = 0; o < 2; o++) {
            auto [v, c] = go(1 << i, o ? a[i].second : a[i].first,
                             o ? a[i].first : a[i].second, 0);
            v += o;
            if (v < ans.first)
                ans = {v, c};
            else if (v == ans.first)
                ans.second += c;
        }
    if (ans.first >= INF)
        cout << "IMPOSSIBLE\n";
    else
        cout << ans.first << ' ' << ans.second << '\n';
}

