import sys
from functools import lru_cache

it = iter(map(int, sys.stdin.buffer.read().split()))
n = next(it)
a = [(next(it), next(it)) for _ in range(n)]
full = (1 << n) - 1
INF = 100


@lru_cache(None)
def go(mask, l, r, sg):
    if mask == full:
        return 0, 1
    best, cnt = INF, 0
    for i, (u, v) in enumerate(a):
        if mask >> i & 1:
            continue
        for o, (x, y) in enumerate(((u, v), (v, u))):
            if x != r:
                continue
            ns = sg
            if mask.bit_count() >= 2:
                if l == r:
                    continue
                ns = 1 if r > l else 2
                if ns == sg:
                    continue
            cost, c = go(mask | 1 << i, x, y, ns)
            cost += o
            if cost < best:
                best, cnt = cost, c
            elif cost == best:
                cnt += c
    return best, cnt


best, cnt = INF, 0
for i, (u, v) in enumerate(a):
    for o, (x, y) in enumerate(((u, v), (v, u))):
        cost, c = go(1 << i, x, y, 0)
        cost += o
        if cost < best:
            best, cnt = cost, c
        elif cost == best:
            cnt += c
print("IMPOSSIBLE") if best >= INF else print(best, cnt)

