        left.push_back(e[i].first);
        len.push_back(e[i + 1].first - e[i].first);
    }
    ll cnt = 0, sum = 0, high = 0, start = 0;
    for (int i = 0; i < (int)h.size(); i++)
        if (h[i] > 0 && h[i] > (i ? h[i - 1] : 0) &&
            h[i] > (i + 1 < (int)h.size() ? h[i + 1] : 0)) {
            cnt++;
            sum += len[i];
            if (h[i] > high) {
                high = h[i];
                start = left[i];
            }
        }
    cout << cnt << ' ' << sum << ' ' << high << ' ' << start << '\n';
