#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    int n, m, B;
    cin >> n >> m >> B;
    vector<int> d(n), ind(n), unlock(n, -1), done(n, -1);
    for (int &x : d)
        cin >> x;
    vector<vector<int>> g(n);
    while (m--) {
        int u, v;
        cin >> u >> v;
        g[--u].push_back(--v);
        ind[v]++;
    }
    for (int i = 0; i < n; i++)
        if (!ind[i])
            unlock[i] = 1;
    int round = 1, cnt = 0;
    ll late = 0;
    while (true) {
        vector<int> v;
        for (int i = 0; i < n; i++)
            if (done[i] < 0 && unlock[i] > 0 && unlock[i] <= round)
                v.push_back(i);
        if (v.empty())
            break;
        sort(v.begin(), v.end(), [&](int x, int y) {
            return tie(unlock[x], d[x], x) < tie(unlock[y], d[y], y);
        });
        if ((int)v.size() > B)
            v.resize(B);
        for (int u : v) {
            done[u] = round;
            cnt++;
            late += max(0, round - d[u]);
        }
        for (int u : v)
            for (int w : g[u])
                if (--ind[w] == 0)
                    unlock[w] = round + 1;
        round++;
    }
    cout << (cnt == n ? round - 1 : -1) << ' ' << cnt << ' ' << late << '\n';
    for (int i = 0; i < n; i++)
        cout << done[i] << (i + 1 == n ? '\n' : ' ');
}

