int main() {
    int n;
    ll K;
    cin >> n >> K;
    vector<ll> s(n + 1);
    for (int i = 0; i < n; i++) {
        ll x;
        cin >> x;
        s[i + 1] = s[i] + x;
    }
    const ll INF = LLONG_MAX / 4;
    vector<vector<ll>> d(n, vector<ll>(n, INF)), w(n, vector<ll>(n));
    for (int i = 0; i < n; i++)
        d[i][i] = 0, w[i][i] = 1;
    for (int len = 2; len <= n; len++)
        for (int l = 0; l + len <= n; l++) {
            int r = l + len - 1;
            for (int k = l; k < r; k++) {
                ll a = s[k + 1] - s[l], b = s[r + 1] - s[k + 1];
                if ((a - b) % K || d[l][k] == INF || d[k + 1][r] == INF)
                    continue;
                ll v = d[l][k] + d[k + 1][r] + abs(a - b), c = w[l][k] * w[k + 1][r];
                if (v < d[l][r])
                    d[l][r] = v, w[l][r] = c;
                else if (v == d[l][r])
                    w[l][r] += c;
            }
        }
    if (d[0][n - 1] == INF)
