const ll MOD = 1000000007;
struct T {
    array<int, 2> to;
    array<ll, 2> g;
};
T cat(T a, T b) {
    T c;
    for (int s = 0; s < 2; s++) {
        c.to[s] = b.to[a.to[s]];
        c.g[s] = (a.g[s] + b.g[a.to[s]]) % MOD;
    }
    return c;
}
int main() {
    int n;
