    vector<T> st;
    for (int i = 0; i < n; i++) {
        char c = s[i];
        if (c == '(') {
            st.push_back(cur);
            cur = id;
        } else if (c == ')') {
            int k = s[++i] - '0';
            T rep = id;
            while (k--)
                rep = cat(rep, cur);
            cur = cat(st.back(), rep);
            st.pop_back();
        } else {
            T x = c == 'F'   ? T{{1, 0}, {0, 0}}
                  : c == 'A' ? T{{0, 1}, {1, 0}}
                             : T{{0, 1}, {0, 1}};
            cur = cat(cur, x);
        }
    }
    cout << cur.to[0] << ' ' << cur.g[0] << '\n';
}

