#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    unsigned long long N;
    int K;
    cin >> N >> K;
    map<tuple<int, int, int, int, bool>, pair<ll, ll>> memo;
    function<pair<ll, ll>(int, int, int, int, bool)> go =
        [&](int pos, int k, int prev, int cur, bool tight) -> pair<ll, ll> {
        if (k > K)
            return {0, 0};
        if (pos < 0) {
            if (cur) {
                if (cur <= prev)
                    return {0, 0};
                k++;
            }
            return {k == K, 0};
        }
        auto key = make_tuple(pos, k, prev, cur, tight);
        if (memo.count(key))
            return memo[key];
        ll count = 0, sum = 0;
        int lim = tight ? ((N >> pos) & 1) : 1;
        for (int b = 0; b <= lim; b++) {
            int nk = k, np = prev, nc = cur;
            if (b)
                nc++;
            else if (cur) {
                if (cur <= prev)
                    continue;
                nk++;
                np = cur;
                nc = 0;
            }
            auto [c, s] = go(pos - 1, nk, np, nc, tight && b == lim);
            count += c;
            sum += s + (b ? c * (1LL << pos) : 0);
        }
        return memo[key] = {count, sum};
    };
    auto [c, s] = go(31, 0, 0, 0, true);
    cout << c << ' ' << s << '\n';
}

