from functools import lru_cache

N, K = map(int, sys.stdin.buffer.read().split())


@lru_cache(None)
def go(pos, k, prev, cur, tight):
    if k > K:
        return 0, 0
    if pos < 0:
        if cur:
            if cur <= prev:
                return 0, 0
            k += 1
        return int(k == K), 0
    lim = (N >> pos) & 1 if tight else 1
    count = total = 0
    for b in range(lim + 1):
        nk, np, nc = k, prev, cur
        if b:
            nc += 1
        elif cur:
            if cur <= prev:
                continue
            nk += 1
            np = cur
            nc = 0
        c, s = go(pos - 1, nk, np, nc, tight and b == lim)
        count += c
        total += s + (c << pos if b else 0)
    return count, total


print(*go(31, 0, 0, 0, True))

