    vector<pair<char, int>> v;
    for (char c : s) {
        if (!v.empty() && v.back().first == c)
            v.back().second++;
        else
            v.push_back({c, 1});
    }
    auto close = [](auto &v) {
        if (v.size() > 1 && v.front().first == v.back().first) {
            v.front().second += v.back().second;
            v.pop_back();
        }
    };
    close(v);
    int rounds = 0, last = 0;
    while (v.size() > 1) {
        int k = v.size(), cut = 0;
        vector<bool> del(k);
        for (int i = 0; i < k; i++)
            if (v[i].second < v[(i + k - 1) % k].second &&
                v[i].second < v[(i + 1) % k].second)
                del[i] = true, cut += v[i].second;
        if (!cut)
            break;
        vector<pair<char, int>> w;
        for (int i = 0; i < k; i++)
            if (!del[i]) {
                if (!w.empty() && w.back().first == v[i].first)
                    w.back().second += v[i].second;
                else
                    w.push_back(v[i]);
            }
        close(w);
        v = move(w);
        rounds++;
        last = cut;
    }
    int rem = 0;
    for (auto [c, k] : v)
        rem += k;
    cout << rounds << ' ' << rem << ' ' << v.size() << ' ' << last << '\n';
}

