    function<pair<ll, ll>(int, int, int, int)> go = [&](int l, int r, int h,
                                                        int p) -> pair<ll, ll> {
        if (l > r)
            return {0, 1};
        if (!h || (r - l + 1) % 2)
            return {INF, 0};
        auto key = make_tuple(l, r, h, p);
        if (memo.count(key))
            return memo[key];
        pair<ll, ll> best = {INF, 0};
        for (int k = l + 1; k <= r; k += 2)
            for (int t = 0; t < 2; t++)
                if (t != p) {
                    auto [a, x] = go(l + 1, k - 1, h - 1, t);
                    auto [b, y] = go(k + 1, r, h, p);
                    if (a == INF || b == INF)
                        continue;
                    char op = t ? '[' : '(', cl = t ? ']' : ')';
                    ll v = a + b + (s[l] == op ? 0 : c[l]) + (s[k] == cl ? 0 : c[k]);
                    if (v < best.first)
                        best = {v, x * y};
                    else if (v == best.first)
                        best.second += x * y;
                }
        return memo[key] = best;
    };
    auto [v, w] = go(0, n - 1, H, 2);
    if (v == INF)
        cout << "-1 0\n";
    else
