#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using I = __int128_t;
I fs(I n, I m, I a, I b) {
    I ans = 0;
    while (true) {
        if (a >= m) {
            ans += (n - 1) * n * (a / m) / 2;
            a %= m;
        }
        if (b >= m) {
            ans += n * (b / m);
            b %= m;
        }
        I y = a * n + b;
        if (y < m)
            break;
        n = y / m;
        b = y % m;
        swap(m, a);
    }
    return ans;
}
int main() {
    ll nn, aa, bb, mm, dd, rr;
    cin >> nn >> aa >> bb >> mm >> dd >> rr;
    I N = nn, A = aa, B = bb, L = I(mm) * dd, lo = I(rr) * mm, hi = lo + mm;
    auto below = [&](I n, I c) { return n - fs(n, L, A, B + L - c) + fs(n, L, A, B); };
    auto count = [&](I n, I l, I r) {
        return n <= 0 || l >= r ? I(0) : below(n, r) - below(n, l);
    };
    I hits = count(N, lo, hi), pairs = 0, shift = A % L;
    for (int k = -1; k <= 1; k++) {
        I l = max(lo, lo - shift + k * L), r = min(hi, hi - shift + k * L);
        pairs += count(N - 1, l, r);
    }
    cout << (ll)hits << ' ' << (ll)(hits - pairs) << '\n';
}

