import sys

N, A, B, M, D, R = map(int, sys.stdin.buffer.read().split())
L = M * D
lo = R * M
hi = lo + M


def fs(n, m, a, b):
    ans = 0
    while True:
        if a >= m:
            ans += (n - 1) * n * (a // m) // 2
            a %= m
        if b >= m:
            ans += n * (b // m)
            b %= m
        y = a * n + b
        if y < m:
            return ans
        n, b = y // m, y % m
        m, a = a, m


def below(n, c):
    return n - fs(n, L, A, B + L - c) + fs(n, L, A, B)


def count(n, l, r):
    return 0 if n <= 0 or l >= r else below(n, r) - below(n, l)


hits = count(N, lo, hi)
shift = A % L
pairs = sum(
    count(N - 1, max(lo, lo - shift + k * L), min(hi, hi - shift + k * L))
    for k in (-1, 0, 1)
)
print(hits, hits - pairs)

