        cin >> x;
    const ll NEG = LLONG_MIN / 4, MOD = 1000000007;
    using S = array<array<pair<ll, ll>, 2>, 2>;
    vector<S> d(K + 1), nd(K + 1);
    auto clear = [&](auto &v) {
        for (auto &s : v)
            for (auto &t : s)
                for (auto &z : t)
                    z = {NEG, 0};
    };
    clear(d);
    d[0][0][0] = {0, 1};
    auto put = [&](pair<ll, ll> &z, ll v, ll w) {
        if (v > z.first)
            z = {v, w};
        else if (v == z.first)
            z.second = (z.second + w) % MOD;
    };
    for (ll x : a) {
        clear(nd);
        for (int j = 0; j <= K; j++)
            for (int b = 0; b < 2; b++)
                for (int p = 0; p < 2; p++) {
                    auto [v, w] = d[j][b][p];
                    if (v == NEG)
                        continue;
                    put(nd[j][b][0], v, w);
                    if (j < K && b + p <= 1)
                        put(nd[j + 1][b + p][1], v + x, w);
                }
        d.swap(nd);
    }
    pair<ll, ll> ans = {NEG, 0};
    for (int p = 0; p < 2; p++)
        if (d[K][1][p].first != NEG)
            put(ans, d[K][1][p].first, d[K][1][p].second);
    if (ans.first == NEG)
        cout << "NONE\n";
    else
        cout << ans.first << ' ' << ans.second << '\n';
